<?phprequire_once 'session_check.php';check_session(['Admin', 'Manager']);// Check if action is download_templateif ($_SERVER["REQUEST_METHOD"] == "POST" && isset($_POST['action']) && $_POST['action'] === 'download_template') {    // Include PhpSpreadsheet library    require 'vendor/autoload.php';    try {        // Create new Spreadsheet object        $spreadsheet = new \PhpOffice\PhpSpreadsheet\Spreadsheet();        $sheet = $spreadsheet->getActiveSheet();        $headers = ['product_name', 'allergens', 'ingredients', 'healthy_option', 'recipe', 'categories', 'groups','image_url'];        $sheet->fromArray([$headers], NULL, 'A1');        // Add sample data        $sampleData = [            ['Chicken Salad', 'Eggs, Dairy', 'Chicken, Lettuce, Tomato, Cucumber, Dressing', 'Green', 'Mix all ingredients together', 'Lunch, Salads', 'Hot Food, Low Carb'],            ['Beef Burger', 'Gluten, Dairy', 'Beef patty, Bun, Cheese, Lettuce, Tomato', 'Amber', 'Grill beef patty, assemble burger', 'Lunch, Sandwiches', 'Hot Food, High Protein']        ];        $sheet->fromArray(null, NULL, 'A2');        // Style header row        $headerStyle = [            'font' => [                'bold' => true,            ],            'fill' => [                'fillType' => \PhpOffice\PhpSpreadsheet\Style\Fill::FILL_SOLID,                'startColor' => [                    'rgb' => 'E0E0E0',                ],            ],        ];        $sheet->getStyle('A1:' . \PhpOffice\PhpSpreadsheet\Cell\Coordinate::stringFromColumnIndex(count($headers) - 1) . '1')->applyFromArray($headerStyle);        // Auto-size columns        foreach (range('A', \PhpOffice\PhpSpreadsheet\Cell\Coordinate::stringFromColumnIndex(count($headers) - 1)) as $col) {            $sheet->getColumnDimension($col)->setAutoSize(true);        }        // Create Excel writer        $writer = new \PhpOffice\PhpSpreadsheet\Writer\Xlsx($spreadsheet);        // Set headers for file download        header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');        header('Content-Disposition: attachment; filename="zouki_product_import_template.xlsx"');        header('Cache-Control: max-age=0');        // Save file to output        $writer->save('php://output');        exit();    } catch (Exception $e) {        // Redirect back with error        $_SESSION['error'] = "Error generating template: " . $e->getMessage();        header("Location: product_import_export.php");        exit();    }} else {    // Not a valid request, redirect to main page    header("Location: product_import_export.php");    exit();}?>